38|// Per-column sum: walk column by column. Each access is (data_[0 * cols + c],
39|// data_[1 * cols + c], ...). The stride between accesses is `cols` doubles,
40|// which is much larger than a typical cache line (64 bytes / 8 doubles).
41|// On a 1024x1024 matrix this strides by 8KB per access, blowing the L1
42|// cache on every load. This is the slow path callers complain about.
43|std::vector<double> Matrix::SumPerColumn() const {
44|    std::vector<double> result(cols_, 0.0);
45|    for (std::size_t c = 0; c < cols_; ++c) {
46|        double s = 0.0;
47|        for (std::size_t r = 0; r < rows_; ++r) {
48|            s += at(r, c);
49|        }
50|        result[c] = s;
51|    }
52|    return result;
53|}
