std::vector<double> Matrix::SumPerColumn() const {
    std::vector<std::size_t> row_indices(rows_);
    std::iota(row_indices.begin(), row_indices.end(), 0);
    std::vector<double> result(cols_);
    std::transform(row_indices.begin(), row_indices.end(), result.begin(),
                   [this](std::size_t r) {
                       return std::accumulate(
                           row_indices.begin(), row_indices.end(), 0.0,
                           [this, r](double acc, std::size_t rr) {
                               return acc + at(rr, r);
                           });
                   });
    return result;
}

